const delay=ms=>new Promise(r=>setTimeout(r,ms));let ws,id=0,loaded=0;const pending=new Map(),checks=[],layouts=[],styleChecks=[],errors=[],external=[];
function call(method,params={}){return new Promise((r,j)=>{const n=++id;const timer=setTimeout(()=>{pending.delete(n);j(Error('Owned browser diagnostic command stalled: '+method));},45000);pending.set(n,{r:v=>{clearTimeout(timer);r(v)},j:e=>{clearTimeout(timer);j(e)}});ws.send(JSON.stringify({id:n,method,params}));});}
async function ev(expression){const r=await call('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true,userGesture:true});if(r.exceptionDetails)throw Error(JSON.stringify(r.exceptionDetails));return r.result.value;}
async function click(selector){const pos=await ev(`(()=>{const e=document.querySelector(${JSON.stringify(selector)});if(!e||e.disabled)throw Error('missing/enabled '+${JSON.stringify(selector)});e.scrollIntoView({block:'center'});const r=e.getBoundingClientRect();if(!r.width||!r.height)throw Error('not visible '+${JSON.stringify(selector)});const hit=document.elementFromPoint(r.x+r.width/2,r.y+r.height/2);if(!e.contains(hit))throw Error('obscured '+${JSON.stringify(selector)});return{x:r.x+r.width/2,y:r.y+r.height/2}})()`);await call('Input.dispatchMouseEvent',{type:'mousePressed',...pos,button:'left',clickCount:1});await call('Input.dispatchMouseEvent',{type:'mouseReleased',...pos,button:'left',clickCount:1});await delay(90);}
async function type(selector,text){await ev(`(()=>{const e=document.querySelector(${JSON.stringify(selector)});if(!e)throw Error('input missing');e.value=${JSON.stringify(text)};e.dispatchEvent(new Event('input',{bubbles:true}))})()`);}
async function viewport(w){await call('Emulation.setDeviceMetricsOverride',{width:w,height:w===1440?1000:844,deviceScaleFactor:1,mobile:w<721});}
async function go(p){await ev(`go(${JSON.stringify(p)})`);await delay(100);}
function mark(name){checks.push({name,pass:true});console.log('PASS '+name);}
async function snap(name){const r=await call('Page.captureScreenshot',{format:'png',fromSurface:true});fs.writeFileSync(evidence+'/screenshots/'+name+'.png',Buffer.from(r.data,'base64'));}
async function geometry(name){await ev('Promise.all([...document.images].filter(e=>e.getBoundingClientRect().width).map(e=>e.decode().catch(()=>null)))');const g=await ev(`({width:innerWidth,scroll:document.documentElement.scrollWidth,dialog:document.querySelector('dialog[open]')?.getBoundingClientRect().toJSON(),badImages:[...document.images].filter(e=>e.getBoundingClientRect().width&&!e.naturalWidth).map(e=>e.src)})`);assert(g.scroll<=g.width+1,name+JSON.stringify(g));assert(!g.badImages.length,name+JSON.stringify(g));if(g.dialog)assert(g.dialog.x>=-1&&g.dialog.right<=g.width+1,name+JSON.stringify(g));const styles=await ev(`(()=>{const selectors=['.juyi-page','.production-page-header','.all-pages-panel','.baseline-page','.panel-return','.composer-input-area','.composer-send','.hall-conversation-history'];return Object.fromEntries(selectors.map(selector=>{const e=document.querySelector(selector);if(!e)return[selector,null];const s=getComputedStyle(e);return[selector,{background:s.backgroundColor,color:s.color,font:s.fontFamily,fontSize:s.fontSize,lineHeight:s.lineHeight,borderRadius:s.borderRadius,padding:s.padding,display:s.display}]}))})()`);layouts.push({name,...g,styles});}
