async function auditPageStyle(pageName,width){
 await call('Input.dispatchMouseEvent',{type:'mouseMoved',x:0,y:0});await delay(100);
 const audit=await ev(`(()=>{const visible=e=>e.getBoundingClientRect().width>0&&e.getBoundingClientRect().height>0;const style=e=>{const s=getComputedStyle(e),r=e.getBoundingClientRect();return {selector:e.className,focused:e.matches(':focus-visible'),font:s.fontFamily,color:s.color,background:s.backgroundColor,width:r.width,height:r.height,svg:!!e.querySelector('svg'),label:e.getAttribute('aria-label'),text:e.textContent.trim()}};return {fontFailures:[...document.querySelectorAll('button,input,textarea,select')].filter(visible).filter(e=>!e.matches('.overview-map-link')&&!getComputedStyle(e).fontFamily.includes('sans-serif')).map(style),close:[...document.querySelectorAll('.panel-close,.ui-close')].filter(visible).map(style),primary:[...document.querySelectorAll('.treasure-primary,.matter-primary-action:not(.simplify-secondary),.composer-send,.overview-quick-request button.primary,.draft-actions .primary')].filter(e=>visible(e)&&!e.disabled).map(style),tokens:Object.fromEntries(['--hall-canvas','--hall-surface','--hall-text','--hall-brand','--hall-text-muted'].map(k=>[k,getComputedStyle(document.body).getPropertyValue(k).trim()]))}})()`);
 assert.deepEqual(audit.fontFailures,[],pageName+' control font '+JSON.stringify(audit.fontFailures));
 for(const c of audit.close){assert(c.svg&&c.label&&!c.text,pageName+' accessible SVG close '+JSON.stringify(c));assert(c.width===44&&c.height===44,pageName+' close size '+JSON.stringify(c));assert.equal(c.color,c.focused?'rgb(146, 63, 48)':'rgb(104, 113, 107)',pageName+' close color '+JSON.stringify(c));}
 for(const c of audit.primary)assert.equal(c.background,'rgb(146, 63, 48)',pageName+' primary color '+JSON.stringify(c));
 assert.equal(audit.tokens['--hall-brand'],'#923f30');assert.equal(audit.tokens['--hall-surface'],'#fffefa');styleChecks.push({page:pageName,width,...audit});
}

